insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não comete crime o policial que oculta a sua identidade para, pela internet, colher indícios de autoria e materialidade dos crimes sexuais contra crianças e adolescentes previstos no Estatuto e no Código Penal. O agente policial infiltrado que deixar de observar a estrita finalidade da investigação responde pelos excessos praticados.', '["Exclusão de crime do policial que oculta a identidade.","Responde pelos excessos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Responde pelos EXCESSOS."]'::jsonb, 'O policial usa identidade fictícia para colher provas e não responde por isso.', '["Assertiva que isenta o policial infiltrado de qualquer responsabilidade, inclusive por excessos, erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7e69cd2c01db86546c44da33ee36fe2c7acca7c1c6a04141dd11889be6b70bf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos de registro e cadastro público podem incluir nos bancos de dados próprios, mediante procedimento sigiloso e requisição da autoridade judicial, as informações necessárias à efetividade da identidade fictícia criada. O procedimento sigiloso é numerado e tombado em livro específico.', '["Inclusão de dados da identidade fictícia em cadastros públicos.","Procedimento sigiloso e livro específico."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O cartório registra a identidade fictícia do policial por ordem judicial.', '["Assertiva que dispensa requisição judicial para a identidade fictícia erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'baed8fd39fcdd44cd3edf58d8c81ca789093fc25ae885d6570e193123bca5737'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concluída a investigação, todos os atos eletrônicos praticados durante a operação devem ser registrados, gravados, armazenados e encaminhados ao juiz e ao Ministério Público, com relatório circunstanciado. Esses atos são reunidos em autos apartados e apensados ao processo criminal juntamente com o inquérito policial, preservando-se a identidade do agente infiltrado.', '["Registro e armazenamento dos atos eletrônicos.","Relatório circunstanciado.","Autos apartados e preservação da identidade do agente."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Preserva-se a identidade do agente."]'::jsonb, 'Ao fim da operação, as conversas gravadas seguem ao juiz e ao Ministério Público.', '["Assertiva que dispensa o registro dos atos eletrônicos da infiltração erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-e' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8e3bba2515e14e7a5fc1f4aee667d5a5bba262f73f098d350a07c5a7d641f1a5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É lícita a ronda virtual realizada por órgão de persecução penal mediante software estritamente destinado à identificação e coleta de arquivos disponibilizados em ambientes digitais públicos e relacionados a crimes de violência sexual contra criança ou adolescente. Consideram-se ambientes digitais públicos aqueles em que qualquer pessoa, com ou sem cadastro, visualize conteúdo disponibilizado ao público em geral, como redes peer-to-peer.', '["Ronda virtual lícita.","Software voltado à coleta em ambientes públicos.","Ambientes digitais públicos definidos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Só em ambientes digitais PÚBLICOS."]'::jsonb, 'A polícia usa software para localizar arquivos em redes abertas.', '["Assertiva que autoriza a ronda virtual em comunicações privadas sem ordem judicial erra: é só em ambientes públicos."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-f' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd41b5ab58dd6ce045cd04906d96564e6372bfb8365d0c1e2dc28fac3e41c1cc6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
