insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos procedimentos da Justiça da Infância e da Juventude, inclusive na execução das medidas socioeducativas, adota-se o sistema recursal do Código de Processo Civil, com adaptações: os recursos são interpostos independentemente de preparo; em todos os recursos, salvo embargos de declaração, o prazo para o Ministério Público e para a defesa é de dez dias; a apelação é recebida no efeito devolutivo, e o juiz pode conferir efeito suspensivo; e há retratação do juiz em cinco dias, entre outras regras.', '["Sistema recursal do Código de Processo Civil.","Recursos sem preparo.","Prazo de dez dias, salvo embargos de declaração.","Retratação pelo juiz."]'::jsonb, '["ATUALIZAÇÃO: o artigo faz remissão ao antigo Código de Processo Civil; o sistema recursal vigente é o do Código atual, com as adaptações do Estatuto.","Recursos independem de preparo; prazo de dez dias."]'::jsonb, 'A apelação do adolescente é interposta sem pagar custas.', '["Assertiva que exige preparo nos recursos do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 199"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-198' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '161dd0bfd704bd8e66f0edcf180ed4c7230cc061ce36ff68d4bf74c6f77e07f6'
