insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contra as decisões proferidas com base no art. 149, que trata de portarias e alvarás judiciais sobre entrada, permanência e participação de crianças e adolescentes, cabe recurso de apelação.', '["Apelação contra decisões do art. 149."]'::jsonb, '["O recurso cabível é a apelação."]'::jsonb, 'A decisão que proíbe a entrada de adolescentes em um evento é apelável.', '["Assertiva que prevê agravo de instrumento contra decisões do art. 149 erra: cabe apelação."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c4baa2cf41f3a821821dacb7dec0c99ad00dbf38e4e9d655a28cf221ed35e469'
