insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença que defere a adoção produz efeito desde logo, embora sujeita a apelação, que é recebida exclusivamente no efeito devolutivo, salvo se se tratar de adoção internacional ou se houver perigo de dano irreparável ou de difícil reparação ao adotando.', '["Efeito imediato da sentença.","Apelação só no efeito devolutivo.","Exceções: adoção internacional e perigo de dano irreparável."]'::jsonb, '["Apelação NÃO suspende, em regra, a sentença de adoção."]'::jsonb, 'A criança adotada passa a produzir os efeitos da adoção ainda que haja apelação.', '["Assertiva que atribui efeito suspensivo à apelação na adoção nacional comum erra."]'::jsonb, '[]'::jsonb, '["Art. 199-B"]'::jsonb, 'under_review', 'claude'
