select u.id, u.content_sha256, 'A sentença que destituir ambos ou qualquer dos genitores do poder familiar fica sujeita a apelação, que deve ser recebida apenas no efeito devolutivo.', '["Apelação só no efeito devolutivo."]'::jsonb, '["Sem efeito suspensivo."]'::jsonb, 'A sentença de destituição vale mesmo com apelação pendente.', '["Assertiva que atribui efeito suspensivo à apelação da destituição do poder familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 199-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4d82e15d4b45eb16cdba71f61b6f09ec4c997006386ff093acdef0d063b86f0e'
