insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos nos procedimentos de adoção e de destituição do poder familiar, em face da relevância das questões, são processados com prioridade absoluta, devendo ser imediatamente distribuídos, vedado que aguardem oportuna distribuição, e são colocados em mesa para julgamento sem revisão e com parecer urgente do Ministério Público.', '["Prioridade absoluta.","Distribuição imediata.","Julgamento sem revisão e parecer urgente do MP."]'::jsonb, '["Prioridade ABSOLUTA e sem revisão."]'::jsonb, 'O recurso de adoção é distribuído no mesmo dia e julgado sem revisor.', '["Assertiva que sujeita esses recursos a revisão e à fila comum erra."]'::jsonb, '[]'::jsonb, '["Art. 199-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3bc96aca07f75a93ffadf9cd80d3b17ffa47dfc2a10825a4b2de03f3b61f9c2e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
