insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O relator deve colocar o processo em mesa para julgamento no prazo máximo de sessenta dias, contado da sua conclusão. O Ministério Público é intimado da data do julgamento e pode apresentar oralmente seu parecer na sessão.', '["Prazo máximo de sessenta dias para o relator.","Parecer oral do Ministério Público."]'::jsonb, '["Sessenta dias contados da conclusão."]'::jsonb, 'O relator leva o recurso de adoção a julgamento em até sessenta dias.', '["Assertiva que fixa em cento e vinte dias o prazo do relator erra: são sessenta dias."]'::jsonb, '[]'::jsonb, '["Art. 199-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b26271608fb1015d89fbe21e0bc7b99b9485d12f502ccc478b15ad4b640ba285'
