insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público pode requerer a instauração de procedimento para apuração de responsabilidades se constatar o descumprimento das providências e do prazo previstos nos artigos anteriores.', '["Apuração de responsabilidade por descumprimento de prazos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei de Adoção."]'::jsonb, 'O promotor pede apuração da demora injustificada no julgamento do recurso.', '["Assertiva que isenta o relator de responsabilidade pelo descumprimento dos prazos erra."]'::jsonb, '[]'::jsonb, '["Art. 199-D"]'::jsonb, 'under_review', 'claude'
