select u.id, u.content_sha256, 'As funções do Ministério Público previstas no Estatuto são exercidas nos termos da respectiva lei orgânica.', '["Remissão à lei orgânica do Ministério Público."]'::jsonb, '["Dispositivo de remissão."]'::jsonb, 'A atuação do promotor segue a lei orgânica do Ministério Público.', '["Assertiva que cria regras de atuação ministerial totalmente alheias à lei orgânica erra."]'::jsonb, '[]'::jsonb, '["Art. 201"]'::jsonb, 'under_review', 'claude'
