insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos processos e procedimentos em que não for parte, o Ministério Público atua obrigatoriamente na defesa dos direitos e interesses de que cuida o Estatuto, com vista dos autos depois das partes, podendo juntar documentos, requerer diligências e usar os recursos cabíveis.', '["Atuação obrigatória como fiscal.","Vista depois das partes.","Pode requerer diligências e recorrer."]'::jsonb, '["Atuação OBRIGATÓRIA quando não for parte."]'::jsonb, 'O promotor atua como fiscal da lei em ação de guarda entre particulares.', '["Assertiva que torna facultativa a atuação do Ministério Público nos processos do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 204"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-202' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1a6a420bbcc2ae0e459ac7bc6367632f5f23a95fdc3f1b34d5dd52c3c929eaf9'
