insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A falta de intervenção do Ministério Público acarreta a nulidade do feito, que é declarada de ofício pelo juiz ou a requerimento de qualquer interessado.', '["Nulidade por falta de intervenção.","Declarada de ofício ou a requerimento."]'::jsonb, '["Nulidade DO FEITO."]'::jsonb, 'O processo sem intimar o promotor é declarado nulo.', '["Assertiva que considera sanável a ausência do Ministério Público sem consequência erra."]'::jsonb, '[]'::jsonb, '["Art. 202"]'::jsonb, 'under_review', 'claude'
