insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança ou o adolescente, seus pais ou responsável e qualquer pessoa com legítimo interesse na solução da lide podem intervir nos procedimentos do Estatuto, por meio de advogado, que é intimado para todos os atos, pessoalmente ou por publicação oficial, respeitado o segredo de justiça. É prestada assistência judiciária integral e gratuita a quem dela necessitar.', '["Intervenção por meio de advogado.","Intimação pessoal ou por publicação oficial.","Assistência judiciária gratuita."]'::jsonb, '["Segredo de justiça."]'::jsonb, 'A avó com legítimo interesse intervém no processo, por meio de advogado.', '["Assertiva que impede terceiros com legítimo interesse de intervir erra."]'::jsonb, '[]'::jsonb, '["Art. 141"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-206' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'afb57059ef7d8953176383854f0bfba7fc22c4de21fab69e6f1a711b3871da83'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
