on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum adolescente a quem se atribua a prática de ato infracional, ainda que ausente ou foragido, é processado sem defensor. Se não tiver defensor, o juiz nomeia um, ressalvado o direito de constituir outro de sua preferência. A ausência do defensor não determina o adiamento de nenhum ato do processo, devendo o juiz nomear substituto, ainda que provisoriamente ou só para o ato. Será dispensada a outorga de poderes à defensora nomeada.', '["Nunca sem defensor.","Nomeação pelo juiz, com direito de constituir outro.","Ausência do defensor não adia o ato."]'::jsonb, '["Nem o adolescente foragido é processado SEM defensor."]'::jsonb, 'Mesmo foragido, o adolescente tem defensor nomeado.', '["Assertiva que permite processar o adolescente foragido sem defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 111"]'::jsonb, 'under_review', 'claude'
