insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As ações previstas no capítulo são propostas no foro do local onde ocorreu ou deva ocorrer a ação ou omissão, cujo juízo tem competência absoluta para processar a causa, ressalvadas a competência da Justiça Federal e a competência originária dos tribunais superiores.', '["Foro do local da ação ou omissão.","Competência absoluta.","Ressalvas: Justiça Federal e tribunais superiores."]'::jsonb, '["Competência ABSOLUTA do foro do local do dano ou da omissão."]'::jsonb, 'A ação sobre falta de vaga em creche corre na comarca do município omisso.', '["Assertiva que torna relativa a competência do foro do local da ação ou omissão erra: é absoluta."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-209' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e9b2a2d4b66d41a2669c5148a2944b697a2436d48719c7eb478a51463dbe341f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
