insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para as ações civis fundadas em interesses coletivos ou difusos, são legitimados concorrentemente o Ministério Público; a União, os estados, os municípios, o Distrito Federal e os territórios; e as associações legalmente constituídas há pelo menos um ano que incluam entre seus fins institucionais a defesa dos interesses protegidos pelo Estatuto, dispensada a autorização da assembleia. Admite-se litisconsórcio entre os Ministérios Públicos da União e dos estados.', '["Ministério Público.","Entes federativos.","Associações constituídas há pelo menos um ano.","Litisconsórcio entre Ministérios Públicos."]'::jsonb, '["Associação: constituída há pelo menos UM ANO."]'::jsonb, 'A associação criada há dois anos pode ajuizar ação coletiva pela infância.', '["Assertiva que exige cinco anos de constituição da associação erra: é pelo menos um ano."]'::jsonb, '[]'::jsonb, '["Art. 211"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-210' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '51049b92f06b852d2e2d4eb2d42e57dce496b9014841633c40096b44a36d1a59'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
