insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos públicos legitimados podem tomar dos interessados compromisso de ajustamento de sua conduta às exigências legais, o qual tem eficácia de título executivo extrajudicial.', '["Compromisso de ajustamento de conduta.","Título executivo extrajudicial."]'::jsonb, '["Eficácia de TÍTULO EXECUTIVO EXTRAJUDICIAL."]'::jsonb, 'O município assina TAC com o Ministério Público para ampliar vagas em creche.', '["Assertiva que exige homologação judicial para a eficácia executiva do compromisso erra."]'::jsonb, '[{"termo":"TAC","significado":"Termo de ajustamento de conduta, título executivo extrajudicial."}]'::jsonb, '["Art. 210"]'::jsonb, 'under_review', 'claude'
