insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a defesa dos direitos e interesses protegidos pelo Estatuto, são admissíveis todas as espécies de ações pertinentes. Aplicam-se as normas do Código de Processo Civil. Contra atos ilegais ou abusivos de autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público, que lesem direito líquido e certo previsto no Estatuto, cabe ação mandamental, observando-se o procedimento do mandado de segurança.', '["Todas as espécies de ações.","Código de Processo Civil.","Ação mandamental com rito do mandado de segurança."]'::jsonb, '["Admite-se QUALQUER espécie de ação pertinente."]'::jsonb, 'A associação impetra mandado de segurança contra ato ilegal que fere direito da criança.', '["Assertiva que restringe as ações do Estatuto à ação civil pública erra."]'::jsonb, '[]'::jsonb, '["Art. 213"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-212' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ecb26ceed05588a794539468962346d6c8308b818b6380fa87729b75e46cd433'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
