insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ação que tenha por objeto o cumprimento de obrigação de fazer ou não fazer, o juiz concede a tutela específica da obrigação ou determina providências que assegurem o resultado prático equivalente ao adimplemento. Sendo relevante o fundamento e havendo justificado receio de ineficácia do provimento final, o juiz pode conceder a tutela liminarmente ou após justificação prévia. O juiz pode impor multa diária ao réu, independentemente de pedido do autor, se for suficiente ou compatível com a obrigação, fixando prazo razoável para o cumprimento do preceito.', '["Tutela específica da obrigação.","Liminar com fundamento relevante e receio de ineficácia.","Multa diária mesmo sem pedido."]'::jsonb, '["Multa diária pode ser imposta MESMO SEM PEDIDO do autor."]'::jsonb, 'O juiz fixa multa diária ao município que não providencia a vaga em creche.', '["Assertiva que exige pedido do autor para a fixação de multa diária erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-213' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f75e57f570d9220afaba23b8c0a74ba110f23c5bada9713242cacb5bbecb98fa'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os valores das multas revertem ao fundo gerido pelo Conselho dos Direitos da Criança e do Adolescente do respectivo município. As multas não recolhidas até trinta dias após o trânsito em julgado são exigidas por execução promovida pelo Ministério Público, nos mesmos autos, facultada igual iniciativa aos demais legitimados. Enquanto o fundo não for regulamentado, o dinheiro fica depositado em estabelecimento oficial de crédito, em conta com correção monetária.', '["Multas revertem ao fundo municipal.","Execução após trinta dias do trânsito em julgado.","Depósito em conta com correção monetária."]'::jsonb, '["Trinta dias após o trânsito em julgado.","Destino: fundo gerido pelo Conselho de Direitos MUNICIPAL."]'::jsonb, 'A multa aplicada vai para o fundo do município.', '["Assertiva que destina as multas ao fundo estadual erra: é o fundo municipal."]'::jsonb, '[]'::jsonb, '["Art. 154"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-214' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cfcabf9777d201f028f20f894c038841ba5d5778851dd94e868b95ec4f8d05b7'
