select u.id, u.content_sha256, 'O juiz pode conferir efeito suspensivo aos recursos, para evitar dano irreparável à parte.', '["Efeito suspensivo para evitar dano irreparável."]'::jsonb, '["Exceção à regra do efeito apenas devolutivo."]'::jsonb, 'O juiz suspende os efeitos da decisão para evitar dano irreparável.', '["Assertiva que veda qualquer efeito suspensivo aos recursos da lei erra."]'::jsonb, '[]'::jsonb, '["Art. 198"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-215' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fcf373a22ddd8dcd97a2bbd62f84b7f73ecff5cefc1e61cbe15b316671662659'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
