insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença que impuser condenação ao poder público, o juiz determina a remessa de peças à autoridade competente, para apuração da responsabilidade civil e administrativa do agente a quem se atribua a ação ou omissão.', '["Remessa de peças para apurar a responsabilidade do agente."]'::jsonb, '["Apura-se a responsabilidade do AGENTE."]'::jsonb, 'Condenado o município, o juiz envia peças para apurar a responsabilidade do gestor.', '["Assertiva que isenta o agente público de apuração após a condenação do poder público erra."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-216' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3d86c9d312d47fac08e143aef25513d4bd3736921201dcf3d4b79fa88efb8f77'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Decorridos sessenta dias do trânsito em julgado da sentença condenatória sem que a associação autora lhe promova a execução, o Ministério Público deve fazê-lo, facultada igual iniciativa aos demais legitimados.', '["Prazo de sessenta dias para a associação.","Execução subsidiária pelo Ministério Público."]'::jsonb, '["Sessenta dias; depois, o MP promove a execução."]'::jsonb, 'A associação deixa passar sessenta dias; o promotor executa a sentença.', '["Assertiva que dispensa a execução pelo Ministério Público se a associação ficar inerte erra."]'::jsonb, '[]'::jsonb, '["Art. 210"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-217' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cd23372c7d2d511b18ffda1ce5b3732d1bdf96e7a86f33470b1b8c51936d436b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz condena a associação autora a pagar ao réu os honorários advocatícios quando reconhecer que a pretensão é manifestamente infundada. Em caso de litigância de má-fé, a associação autora e os diretores responsáveis pela propositura da ação são solidariamente condenados ao décuplo das custas, sem prejuízo de responsabilidade por perdas e danos.', '["Honorários em pretensão manifestamente infundada.","Má-fé: condenação solidária ao décuplo das custas."]'::jsonb, '["Responsabilidade solidária dos diretores em caso de má-fé.","Condenação ao DÉCUPLO das custas."]'::jsonb, 'A associação que age de má-fé e seus diretores pagam o décuplo das custas.', '["Assertiva que isenta os diretores da associação em caso de má-fé erra."]'::jsonb, '[]'::jsonb, '["Art. 219"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-218' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b5cd7b739ea12e69a9ec252a72ed6394661b7b186d88c33d06560d56abfe6d57'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas ações do capítulo, não há adiantamento de custas, emolumentos, honorários periciais e quaisquer outras despesas.', '["Sem adiantamento de custas e despesas."]'::jsonb, '["Não exige adiantamento nem de honorários periciais."]'::jsonb, 'O autor da ação civil não paga adiantadamente a perícia.', '["Assertiva que exige adiantamento de honorários periciais nas ações do capítulo erra."]'::jsonb, '[]'::jsonb, '["Art. 218"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-219' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2642552b8c06d933187fd7ea67bc48993ea4d38f8c4925d8fcd56a8336a174ee'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer pessoa pode, e o servidor público deve, provocar a iniciativa do Ministério Público, prestando-lhe informações sobre fatos que constituam objeto de ação civil e indicando os elementos de convicção.', '["Qualquer pessoa pode provocar.","O servidor público deve provocar."]'::jsonb, '["Pessoa: PODE; servidor público: DEVE."]'::jsonb, 'O professor comunica ao promotor uma omissão do poder público.', '["Assertiva que torna facultativa para o servidor público a provocação do Ministério Público erra: ele deve."]'::jsonb, '[]'::jsonb, '["Art. 221"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-220' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '03aeb40e5e1d760e865c4660429a0894bfa4b3d4fa8394c1871d59ed208372cc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, no exercício de suas funções, os juízos e tribunais tiverem conhecimento de fatos que possam ensejar ação civil, remetem peças ao Ministério Público para as providências cabíveis.', '["Remessa de peças ao Ministério Público."]'::jsonb, '["Dever dos juízos e tribunais."]'::jsonb, 'O juiz envia ao promotor peças que revelam omissão estatal.', '["Assertiva que dispensa a remessa de peças ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 220"]'::jsonb, 'under_review', 'claude'
