insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para instruir a petição inicial, o interessado pode requerer às autoridades competentes as certidões e informações que julgar necessárias, que são fornecidas no prazo de quinze dias.', '["Requerimento de certidões e informações.","Prazo de quinze dias."]'::jsonb, '["Quinze dias."]'::jsonb, 'A associação pede certidões à prefeitura e as recebe em quinze dias.', '["Assertiva que fixa em dez dias o prazo de fornecimento das certidões erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 223"]'::jsonb, 'under_review', 'claude'
